local _chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local _out = {{}}
local _n = 0

for c in _b:gmatch("[^=]") do
    local p = _chars:find(c, 1, true) - 1
    for bit = 5, 0, -1 do
        _n = _n + 1
        _out[_n] = (p >> bit) & 1
    end
end

local _bytes = {{}}
local _bn = 0
for i = 1, #_out - 7, 8 do
    local v = 0
    for j = 0, 7 do
        v = (v << 1) | _out[i + j]
    end
    _bn = _bn + 1
    _bytes[_bn] = string.char(v)
end

local _src = table.concat(_bytes)
local _load = loadstring or load
assert(_load, "Este ambiente não possui loadstring/load.")
